sys_script_include.script:
var VisaGuardianStudentContext = Class.create();

VisaGuardianStudentContext.prototype = {

    initialize: function() {
    },

    getCurrentStudentContext: function(userId) {

        var result = {
            success: false,
            message: '',
            student: {}
        };

        if (!userId) {
            result.message = 'No student user provided.';
            return result;
        }

        var student = new GlideRecord('x_snc_visaguardi_0_student_profile');

        student.addQuery('user', userId);
        student.setLimit(1);
        student.query();

        if (!student.next()) {
            result.message = 'No Student Profile found for the selected user.';
            return result;
        }

        result.success = true;
        result.message = 'Student profile found.';

        result.student = {
            user_id: student.getValue('user_id'),
            first_name: student.getValue('first_name'),
            last_name: student.getValue('last_name'),
            email: student.getValue('email'),
            nationality: student.getValue('nationality'),
            student_id: student.getValue('student_id'),
            degree_program: student.getValue('degree_program'),
            degree_level: student.getValue('degree_level'),
            university_name: student.getValue('university_name'),
            current_semester: student.getValue('current_semester'),
            intake_year: student.getValue('intake_year'),
            current_visa_status: student.getValue('current_visa_status'),
            visa_type: student.getValue('visa_type'),
            visa_expiry_date: student.getValue('visa_expiry_date'),
            passport_expiry_date: student.getValue('passport_expiry_date')
        };

        return result;
    },

    type: 'VisaGuardianStudentContext'
};
